package com.movieticket.movie; import jakarta.persistence.*; import jakarta.validation.constraints.*;
@Entity @Table(name="movies") public class Movie { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank @Column(nullable=false) private String title; @NotBlank @Column(nullable=false) private String genre; @Min(1) @Max(600) private int durationMinutes; @NotBlank private String language; private String description; public Movie(){} public Long getId(){return id;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getGenre(){return genre;} public void setGenre(String v){genre=v;} public int getDurationMinutes(){return durationMinutes;} public void setDurationMinutes(int v){durationMinutes=v;} public String getLanguage(){return language;} public void setLanguage(String v){language=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} }
